using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
namespace Aurora {
internal static class InstallerFixtureCheck {
    static string LogTail(string path){try{if(!File.Exists(path))return "No MSI log";var lines=new Queue<string>();using(var file=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var reader=new StreamReader(file)){string line;while((line=reader.ReadLine())!=null){lines.Enqueue(line);if(lines.Count>70)lines.Dequeue();}}return String.Join("\n",lines);}catch(Exception ex){return "MSI log unavailable: "+ex.Message;}}
    public static int Standalone(){
        if(!ExtendedChecks.Allowed())return 80;
        string folder=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"installer-lab"),report="Installer-only disposable validation • "+DateTime.Now.ToString("s")+Environment.NewLine;int code=0;
        Directory.CreateDirectory(folder);
        try{report+="PASS • "+Run(folder);}catch(PlatformNotSupportedException ex){report+="UNVERIFIED • "+ex.Message;}catch(Exception ex){code=1;report+="FAIL • "+ex;}
        report+=Environment.NewLine+"RESULT • "+code+" failure(s).";
        File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"installer-results.txt"),report);
        if(Directory.Exists(@"C:\OuOResults")){File.WriteAllText(@"C:\OuOResults\installer-results.txt",report);File.WriteAllText(@"C:\OuOResults\msi-log-tail.txt",LogTail(Path.Combine(folder,"msi-install.log")));}
        return code;
    }
    public static string Run(string folder){
        if(!ExtendedChecks.Allowed())throw new InvalidOperationException("Disposable guest only");string code=Guid.NewGuid().ToString("B").ToUpperInvariant(),component=Guid.NewGuid().ToString("B").ToUpperInvariant(),msi=Path.Combine(folder,"OuO-owned-fixture.msi");
        var sql=new List<string>{
            "CREATE TABLE `Property` (`Property` CHAR(72) NOT NULL, `Value` CHAR(0) LOCALIZABLE PRIMARY KEY `Property`)",
            "CREATE TABLE `Directory` (`Directory` CHAR(72) NOT NULL, `Directory_Parent` CHAR(72), `DefaultDir` CHAR(255) NOT NULL LOCALIZABLE PRIMARY KEY `Directory`)",
            "CREATE TABLE `Component` (`Component` CHAR(72) NOT NULL, `ComponentId` CHAR(38), `Directory_` CHAR(72) NOT NULL, `Attributes` SHORT NOT NULL, `Condition` CHAR(255), `KeyPath` CHAR(72) PRIMARY KEY `Component`)",
            "CREATE TABLE `Feature` (`Feature` CHAR(38) NOT NULL, `Feature_Parent` CHAR(38), `Title` CHAR(64) LOCALIZABLE, `Description` CHAR(255) LOCALIZABLE, `Display` SHORT, `Level` SHORT NOT NULL, `Directory_` CHAR(72), `Attributes` SHORT NOT NULL PRIMARY KEY `Feature`)",
            "CREATE TABLE `FeatureComponents` (`Feature_` CHAR(38) NOT NULL, `Component_` CHAR(72) NOT NULL PRIMARY KEY `Feature_`, `Component_`)",
            "CREATE TABLE `Registry` (`Registry` CHAR(72) NOT NULL, `Root` SHORT NOT NULL, `Key` CHAR(255) NOT NULL LOCALIZABLE, `Name` CHAR(255) LOCALIZABLE, `Value` CHAR(0) LOCALIZABLE, `Component_` CHAR(72) NOT NULL PRIMARY KEY `Registry`)",
            "CREATE TABLE `CreateFolder` (`Directory_` CHAR(72) NOT NULL, `Component_` CHAR(72) NOT NULL PRIMARY KEY `Directory_`, `Component_`)",
            "CREATE TABLE `Media` (`DiskId` SHORT NOT NULL, `LastSequence` LONG NOT NULL, `DiskPrompt` CHAR(64) LOCALIZABLE, `Cabinet` CHAR(255), `VolumeLabel` CHAR(32), `Source` CHAR(72) PRIMARY KEY `DiskId`)",
            "CREATE TABLE `InstallExecuteSequence` (`Action` CHAR(72) NOT NULL, `Condition` CHAR(255), `Sequence` SHORT PRIMARY KEY `Action`)"
        };
        sql.Add("INSERT INTO `Media` (`DiskId`,`LastSequence`) VALUES (1,0)");
        foreach(var property in new[]{Tuple.Create("ProductCode",code),Tuple.Create("ProductName","OuO disposable installer validation"),Tuple.Create("Manufacturer","OuO test fixture"),Tuple.Create("ProductVersion","1.0.0"),Tuple.Create("ProductLanguage","1033"),Tuple.Create("ALLUSERS","1"),Tuple.Create("INSTALLLEVEL","1")})sql.Add("INSERT INTO `Property` (`Property`,`Value`) VALUES ('"+property.Item1+"','"+property.Item2+"')");
        sql.Add("INSERT INTO `Directory` (`Directory`,`DefaultDir`) VALUES ('TARGETDIR','SourceDir')");sql.Add("INSERT INTO `Directory` (`Directory`,`Directory_Parent`,`DefaultDir`) VALUES ('ProgramFilesFolder','TARGETDIR','.')");sql.Add("INSERT INTO `Directory` (`Directory`,`Directory_Parent`,`DefaultDir`) VALUES ('INSTALLDIR','ProgramFilesFolder','OUOFIX|OuOLabFixture')");sql.Add("INSERT INTO `Component` (`Component`,`ComponentId`,`Directory_`,`Attributes`,`KeyPath`) VALUES ('OwnedComponent','"+component+"','INSTALLDIR',4,'OwnedReg')");sql.Add("INSERT INTO `Feature` (`Feature`,`Title`,`Display`,`Level`,`Directory_`,`Attributes`) VALUES ('Main','Owned fixture',1,1,'INSTALLDIR',0)");sql.Add("INSERT INTO `FeatureComponents` (`Feature_`,`Component_`) VALUES ('Main','OwnedComponent')");sql.Add("INSERT INTO `Registry` (`Registry`,`Root`,`Key`,`Name`,`Value`,`Component_`) VALUES ('OwnedReg',2,'Software\\OuO\\DisposableValidation','OwnedFixture','yes','OwnedComponent')");sql.Add("INSERT INTO `CreateFolder` (`Directory_`,`Component_`) VALUES ('INSTALLDIR','OwnedComponent')");
        foreach(var action in new[]{Tuple.Create("CostInitialize",800),Tuple.Create("FileCost",900),Tuple.Create("CostFinalize",1000),Tuple.Create("InstallValidate",1400),Tuple.Create("InstallInitialize",1500),Tuple.Create("ProcessComponents",1600),Tuple.Create("UnpublishFeatures",1800),Tuple.Create("RemoveRegistryValues",2600),Tuple.Create("RemoveFiles",3500),Tuple.Create("RemoveFolders",3600),Tuple.Create("CreateFolders",3700),Tuple.Create("WriteRegistryValues",5000),Tuple.Create("RegisterProduct",6100),Tuple.Create("PublishFeatures",6300),Tuple.Create("PublishProduct",6400),Tuple.Create("InstallFinalize",6600)})sql.Add("INSERT INTO `InstallExecuteSequence` (`Action`,`Sequence`) VALUES ('"+action.Item1+"',"+action.Item2+")");
        string script="$ErrorActionPreference='Stop';$invoke=[Reflection.BindingFlags]::InvokeMethod;$wi=New-Object -ComObject WindowsInstaller.Installer;$db=$wi.GetType().InvokeMember('OpenDatabase',$invoke,$null,$wi,@("+Runner.QuotePS(msi)+",3));foreach($sql in @("+String.Join(",",sql.Select(Runner.QuotePS))+")){$v=$db.GetType().InvokeMember('OpenView',$invoke,$null,$db,@($sql));$null=$v.GetType().InvokeMember('Execute',$invoke,$null,$v,$null);$null=$v.GetType().InvokeMember('Close',$invoke,$null,$v,$null)};$sum=$db.GetType().InvokeMember('SummaryInformation',[Reflection.BindingFlags]::GetProperty,$null,$db,@(20));foreach($pair in @(@(2,'OuO fixture'),@(7,'Intel;1033'),@(9,'"+Guid.NewGuid().ToString("B")+"'),@(14,200),@(15,0))){$null=$sum.GetType().InvokeMember('Property',[Reflection.BindingFlags]::SetProperty,$null,$sum,@($pair[0],$pair[1]))};$null=$sum.GetType().InvokeMember('Persist',$invoke,$null,$sum,$null);$null=$db.GetType().InvokeMember('Commit',$invoke,$null,$db,$null);'CREATED'";
        var created=Runner.PS(script,45000);if(created.Code!=0||!File.Exists(msi))throw new InvalidDataException("MSI fixture creation: "+created.Output);
        try{var installed=Runner.Run("msiexec.exe","/i "+Args.Q(msi)+" /qn /norestart /l*v "+Args.Q(Path.Combine(folder,"msi-install.log")),300000,allowBackground:true);if(installed.Code!=0&&installed.Code!=3010)throw new IOException("MSI install code "+installed.Code+" • "+installed.Output);var app=MsiRemoval.Inventory().SingleOrDefault(x=>x.ProductCode==code);if(app==null||app.Name!="OuO disposable installer validation")throw new InvalidDataException("Production inventory did not return installed fixture name.");var removed=MsiRemoval.Uninstall(app);if(removed.Code!=0&&removed.Code!=3010)throw new IOException("Production MSI removal code "+removed.Code);if(MsiRemoval.Inventory().Any(x=>x.ProductCode==code))throw new InvalidDataException("Removed fixture still appears in inventory.");return "Owned MSI installed silently; production inventory returned its name; production uninstaller removed its registration.";
        }catch(Exception ex){string log=Path.Combine(folder,"msi-install.log"),detail=ex.Message+"\n"+LogTail(log);if(ex.Message.StartsWith("MSI install code 1618"))throw new PlatformNotSupportedException("Another installer holds the guest's Windows Installer mutex; a clean Sandbox is needed. "+detail);throw new IOException(detail,ex);}finally{if(MsiRemoval.Inventory().Any(x=>x.ProductCode==code))Runner.Run("msiexec.exe","/x "+code+" /qn /norestart",300000,allowBackground:true);}
    }
}
}
